import Foundation
import Dispatch
@_silgen_name("bench_black_box_u64") func blackBox(_ x: UInt64) -> UInt64
@inline(__always) func now() -> Double { Double(DispatchTime.now().uptimeNanoseconds) * 1e-9 }
func median(_ a:[Double]) -> Double { a.sorted()[a.count/2] }
func emit(_ k:String,_ u:UInt64,_ r:Int,_ s:Double,_ rate:Double,_ c:UInt64){ print(String(format:"RESULT kernel=%@ units=%llu rounds=%d seconds=%.9f rate=%.6f checksum=%llu",k,u,r,s,rate,c)) }
@inline(__always) func mix32(_ xx:UInt32)->UInt32{var x=xx &+ 0x9e3779b9;x ^= x>>16;x = x &* 0x85ebca6b;x ^= x>>13;x = x &* 0xc2b2ae35;return x ^ (x>>16)}
@inline(__always) func hash32(_ xx:UInt32)->UInt32{var x=xx;x ^= x>>16;x = x &* 0x7feb352d;x ^= x>>15;x = x &* 0x846ca68b;return x ^ (x>>16)}
func ck32(_ a:[UInt32])->UInt32{var h:UInt32=2166136261;for x in a{h=(h^x)&*16777619};return h}
func ck64(_ a:[UInt64])->UInt32{var h:UInt32=2166136261;for x in a{h=(h^UInt32(truncatingIfNeeded:x))&*16777619;h=(h^UInt32(truncatingIfNeeded:x>>32))&*16777619};return h}
@inline(never) func integer50(_ n:UInt64)->UInt64{let mask=(UInt64(1)<<50)-1;var x=UInt64(88172645463325252)&mask;var s:UInt64=0;var i:UInt64=0;while i<n{x ^= x>>7;x ^= (x<<8)&mask;x ^= x>>9;x &= mask;s=(s &+ (x ^ (x>>17))) & mask;i+=1};return s}
func benchInteger(_ n:UInt64,_ r:Int){_ = integer50(n/20+1);var t=[Double]();var c:UInt64=0;for _ in 0..<r{let nn=blackBox(n);let a=now();c=blackBox(integer50(nn));t.append(now()-a)};let m=median(t);emit("integer50",n,r,m,Double(n)/m/1e6,c)}
let pattern:[UInt8]=[97,108,112,104,97,34,98,101,116,97,92,103,97,109,109,97,10,9,1,120,121,122,47]
func jsonEscape(_ input:[UInt8],_ out:inout [UInt8])->Int{let hex=Array("0123456789abcdef".utf8);var j=0;out[j]=34;j+=1;for c in input{switch c{case 34:out[j]=92;out[j+1]=34;j+=2;case 92:out[j]=92;out[j+1]=92;j+=2;case 8:out[j]=92;out[j+1]=98;j+=2;case 12:out[j]=92;out[j+1]=102;j+=2;case 10:out[j]=92;out[j+1]=110;j+=2;case 13:out[j]=92;out[j+1]=114;j+=2;case 9:out[j]=92;out[j+1]=116;j+=2;default:if c<32{out[j]=92;out[j+1]=117;out[j+2]=48;out[j+3]=48;out[j+4]=hex[Int(c>>4)];out[j+5]=hex[Int(c&15)];j+=6}else{out[j]=c;j+=1}}};out[j]=34;return j+1}
func benchJSON(_ n:UInt64,_ r:Int){var input=[UInt8](repeating:0,count:Int(n));for i in input.indices{input[i]=pattern[i%23]};var out=[UInt8](repeating:0,count:Int(n)*6+2);var on=jsonEscape(input,&out);var t=[Double]();for _ in 0..<r{let a=now();on=jsonEscape(input,&out);t.append(now()-a)};var c=UInt64(on);for i in 0..<on{c += UInt64(out[i])};let m=median(t);emit("json_escape",n,r,m,Double(n)/m/1e9,c)}
func mergeSort(_ a:inout [UInt32],_ tmp:inout [UInt32]){let n=a.count;var src=a;var dst=tmp;var width=1;var flip=false;while width<n{var lo=0;while lo<n{let mid=min(lo+width,n),hi=min(lo+2*width,n);var i=lo,j=mid,k=lo;while i<mid && j<hi{if src[i]<=src[j]{dst[k]=src[i];i+=1}else{dst[k]=src[j];j+=1};k+=1};while i<mid{dst[k]=src[i];i+=1;k+=1};while j<hi{dst[k]=src[j];j+=1;k+=1};lo += 2*width};swap(&src,&dst);flip.toggle();if width>n/2{break};width*=2};a=src}
func benchMerge(_ nu:UInt64,_ r:Int){let n=Int(nu);let base=(0..<n).map{mix32(UInt32($0))};var a=[UInt32](repeating:0,count:n),tmp=[UInt32](repeating:0,count:n),t=[Double]();for _ in 0..<r{a=base;let q=now();mergeSort(&a,&tmp);t.append(now()-q)};let m=median(t);emit("merge_sort",nu,r,m,Double(n)/m/1e6,UInt64(ck32(a)))}
@inline(__always) func binarySearch(_ a:[UInt32],_ x:UInt32)->Int{var l=0,h=a.count;while l<h{let m=l+(h-l)/2;if a[m]<x{l=m+1}else{h=m}};return l<a.count && a[l]==x ? l:-1}
func benchBS(_ nu:UInt64,_ r:Int){let n=Int(nu),nq=n*4;let a=(0..<n).map{UInt32($0*2)};let q=(0..<nq).map{mix32(UInt32($0))%UInt32(2*n)};var t=[Double](),c:UInt64=0;for _ in 0..<r{let s=now();c=0;for x in q{let p=binarySearch(a,x);if p>=0{c += UInt64(p+1)}};t.append(now()-s)};let m=median(t);emit("binary_search",UInt64(nq),r,m,Double(nq)/m/1e6,c)}
func benchPrefix(_ nu:UInt64,_ r:Int){let n=Int(nu);let input=(0..<n).map{mix32(UInt32($0))&1023};var out=[UInt64](repeating:0,count:n),t=[Double]();var c:UInt32=0;for _ in 0..<r{let q=now();c=0;for z in 0..<16{var s=UInt64(z);for i in 0..<n{s += UInt64(input[i]);out[i]=s};c ^= UInt32(truncatingIfNeeded:s)};t.append(now()-q)};c ^= ck64(out);let m=median(t);emit("prefix_sum",nu*16,r,m,Double(n*16)/m/1e6,UInt64(c))}
func benchMatrix(_ nu:UInt64,_ r:Int){let n=Int(nu),nn=n*n;let a=(0..<nn).map{mix32(UInt32($0))&15};let b=(0..<nn).map{mix32(UInt32($0+nn))&15};var c=[UInt64](repeating:0,count:nn),t=[Double]();for _ in 0..<r{let q=now();for i in 0..<n{for j in 0..<n{var s:UInt64=0;for k in 0..<n{s += UInt64(a[i*n+k])*UInt64(b[k*n+j])};c[i*n+j]=s}};t.append(now()-q)};let m=median(t);emit("matrix_mul",nu,r,m,Double(n*n*n)/m/1e6,UInt64(ck64(c)))}
func graph(_ n:Int,_ d:Int,_ weighted:Bool)->([UInt32],[UInt32]){var a=[UInt32](repeating:0,count:n*d),w=weighted ? [UInt32](repeating:0,count:n*d):[];for i in 0..<n{for e in 0..<d{let p=i*d+e;a[p]=e==0 ? UInt32((i+1)%n):(e==1 ? UInt32((i+n-1)%n):mix32(UInt32(p))%UInt32(n));if weighted{w[p]=1+(mix32(0xabc00000 &+ UInt32(p))&15)}}};return(a,w)}
func benchBFS(_ nu:UInt64,_ r:Int){let n=Int(nu),d=4,passes=16;let(a,_)=graph(n,d,false);var dist=[Int32](repeating:-1,count:n),q=[UInt32](repeating:0,count:n),t=[Double]();var seen:UInt32=0;for _ in 0..<r{let s=now();for z in 0..<passes{for i in 0..<n{dist[i] = -1};var h=0,tt=0;dist[0]=0;q[tt]=0;tt+=1;while h<tt{let u=Int(q[h]);h+=1;let nd=dist[u]+1;for e in 0..<d{let v=Int(a[u*d+e]);if dist[v]<0{dist[v]=nd;q[tt]=UInt32(v);tt+=1}}};seen ^= UInt32(tt+z)};t.append(now()-s)};let du=dist.map{UInt32(bitPattern:$0)};let c=ck32(du)^seen,m=median(t);emit("bfs",nu*UInt64(passes),r,m,Double(n*d*passes)/m/1e6,UInt64(c))}
struct HPair{var d:UInt64;var v:UInt32}
func hpPush(_ h:inout [HPair],_ sz:inout Int,_ x:HPair){var i=sz;sz+=1;while i>0{let p=(i-1)/2;if h[p].d<=x.d{break};h[i]=h[p];i=p};h[i]=x}
func hpPop(_ h:inout [HPair],_ sz:inout Int)->HPair{let o=h[0];sz-=1;let x=h[sz];var i=0;while true{let l=i*2+1;if l>=sz{break};let rr=l+1,c=rr<sz && h[rr].d<h[l].d ? rr:l;if h[c].d>=x.d{break};h[i]=h[c];i=c};if sz>0{h[i]=x};return o}
func benchDij(_ nu:UInt64,_ r:Int){let n=Int(nu),d=4;let(a,w)=graph(n,d,true);var dist=[UInt64](repeating:0,count:n),heap=[HPair](repeating:HPair(d:0,v:0),count:n*d*4),t=[Double]();var c:UInt32=0;for _ in 0..<r{let s=now();for i in 0..<n{dist[i]=UInt64.max/4};var sz=0;dist[0]=0;hpPush(&heap,&sz,HPair(d:0,v:0));while sz>0{let x=hpPop(&heap,&sz),u=Int(x.v);if x.d != dist[u]{continue};for e in 0..<d{let p=u*d+e,v=Int(a[p]),nd=x.d+UInt64(w[p]);if nd<dist[v]{dist[v]=nd;hpPush(&heap,&sz,HPair(d:nd,v:UInt32(v)))}}};c=ck64(dist);t.append(now()-s)};let m=median(t);emit("dijkstra",nu,r,m,Double(n*d)/m/1e6,UInt64(c))}
@inline(__always) func ufFind(_ p:inout [UInt32],_ xx:UInt32)->UInt32{var x=xx;while p[Int(x)] != x{p[Int(x)] = p[Int(p[Int(x)])];x=p[Int(x)]};return x}
func benchUF(_ nu:UInt64,_ r:Int){let n=Int(nu),ops=n*4;let aa=(0..<ops).map{mix32(UInt32($0))%UInt32(n)},bb=(0..<ops).map{mix32(UInt32($0+ops))%UInt32(n)};var p=[UInt32](repeating:0,count:n),rank=[UInt8](repeating:0,count:n),t=[Double]();for _ in 0..<r{let s=now();for i in 0..<n{p[i]=UInt32(i);rank[i]=0};for i in 0..<ops{var ra=ufFind(&p,aa[i]),rb=ufFind(&p,bb[i]);if ra != rb{if rank[Int(ra)]<rank[Int(rb)]{swap(&ra,&rb)};p[Int(rb)]=ra;if rank[Int(ra)]==rank[Int(rb)]{rank[Int(ra)] &+= 1}}};t.append(now()-s)};for i in 0..<n{p[i]=ufFind(&p,UInt32(i))};let m=median(t);emit("union_find",UInt64(ops),r,m,Double(ops)/m/1e6,UInt64(ck32(p)))}
@inline(never) func mandel(_ w:Int,_ mi:Int)->UInt64{var sum:UInt64=0;for y in 0..<w{let ci = -1.5+3.0*Double(y)/Double(w-1);for x in 0..<w{let cr = -2.0+3.0*Double(x)/Double(w-1);var zr=0.0,zi=0.0,it=0;while it<mi{let a=zr*zr,b=zi*zi;if a+b>4{break};let nz=a-b+cr;zi=2*zr*zi+ci;zr=nz;it+=1};sum += UInt64(it)}};return sum}
func benchMandel(_ w:UInt64,_ r:Int){_ = mandel(min(Int(w),128),20);var t=[Double](),c:UInt64=0;for _ in 0..<r{let ww=blackBox(w),s=now();c=blackBox(mandel(Int(ww),50));t.append(now()-s)};let m=median(t);emit("mandelbrot",w*w,r,m,Double(w*w)/m/1e6,c)}
func benchArray(_ nu:UInt64,_ r:Int){let n=Int(nu),input=(0..<Int(nu)).map{mix32(UInt32($0))};var t=[Double](),c:UInt32=0;for _ in 0..<r{let s=now();var v=[UInt32]();for x in input{v.append(x)};var h:UInt32=2166136261;for i in 0..<n{v[i] ^= UInt32(i);h=(h^v[i])&*16777619};while !v.isEmpty{let x=v.removeLast();h=(h^(x &+ UInt32(v.count)))&*16777619};c=h;t.append(now()-s)};let m=median(t);emit("dynamic_array",nu,r,m,Double(n)/m/1e6,UInt64(c))}
func benchList(_ nu:UInt64,_ r:Int){let n=Int(nu),passes=16,base=(0..<Int(nu)).map{mix32(UInt32($0))};var next=[UInt32](repeating:0,count:n),val=[UInt32](repeating:0,count:n),t=[Double]();var c:UInt32=0;for _ in 0..<r{let s=now();val=base;for i in 0..<n{next[i]=i+1<n ? UInt32(i+1):UInt32.max};var b=0;while b<n{let hi=min(b+64,n)-1;for i in b...hi{next[i]=i==b ? (hi+1<n ? UInt32(hi+1):UInt32.max):UInt32(i-1)};b+=64};var h:UInt32=2166136261;for pass in 0..<passes{var cur:UInt32=64<n ? 63:UInt32(n-1),seen=0;while cur != UInt32.max && seen<n{let u=Int(cur);val[u] ^= UInt32(seen+pass);h=(h^(val[u] &+ cur &+ UInt32(pass)))&*16777619;cur=next[u];seen+=1};h=(h^UInt32(seen))&*16777619};c=h;t.append(now()-s)};let m=median(t);emit("linked_list",nu*UInt64(passes),r,m,Double(n*passes)/m/1e6,UInt64(c))}
func benchQueue(_ ops64:UInt64,_ r:Int){let ops=Int(ops64),cap=ops/2+1024,input=(0..<ops).map{mix32(UInt32($0))};var b=[UInt32](repeating:0,count:cap),t=[Double]();var c:UInt32=0;for _ in 0..<r{let s=now();var h=0,tt=0,cnt=0,z:UInt32=0;for i in 0..<ops{if (i&3) != 3{if cnt==cap{z ^= b[h];h=(h+1)%cap;cnt-=1};b[tt]=input[i];tt=(tt+1)%cap;cnt+=1}else if cnt>0{z ^= b[h];h=(h+1)%cap;cnt-=1}};while cnt>0{z ^= b[h];h=(h+1)%cap;cnt-=1};c=z;t.append(now()-s)};let m=median(t);emit("queue_ring",ops64,r,m,Double(ops)/m/1e6,UInt64(c))}
func np2(_ x:Int)->Int{var p=1;while p<x{p <<= 1};return p}
func benchHash(_ nu:UInt64,_ r:Int){let n=Int(nu),cap=np2(n*2),mask=cap-1,ik=(0..<Int(nu)).map{mix32(UInt32($0))|1},iv=(0..<Int(nu)).map{mix32(UInt32($0)&+0x55555555)};var keys=[UInt32](repeating:0,count:cap),vals=[UInt32](repeating:0,count:cap),t=[Double]();var c:UInt32=0;for _ in 0..<r{let s=now();keys=Array(repeating:0,count:cap);for i in 0..<n{let key=ik[i];var p=Int(hash32(key))&mask;while keys[p] != 0 && keys[p] != key{p=(p+1)&mask};keys[p]=key;vals[p]=iv[i]};var h:UInt32=0;for i in 0..<n{let key=ik[i];var p=Int(hash32(key))&mask;while keys[p] != key{p=(p+1)&mask};vals[p] ^= UInt32(i);h ^= vals[p]};c=h;t.append(now()-s)};let m=median(t);emit("hash_table",nu,r,m,Double(n*2)/m/1e6,UInt64(c))}
func heapPush(_ h:inout [UInt32],_ sz:inout Int,_ x:UInt32){var i=sz;sz+=1;while i>0{let p=(i-1)/2;if h[p]<=x{break};h[i]=h[p];i=p};h[i]=x}
func heapPop(_ h:inout [UInt32],_ sz:inout Int)->UInt32{let o=h[0];sz-=1;let x=h[sz];var i=0;while true{let l=i*2+1;if l>=sz{break};let rr=l+1,c=rr<sz && h[rr]<h[l] ? rr:l;if h[c]>=x{break};h[i]=h[c];i=c};if sz>0{h[i]=x};return o}
func benchHeap(_ nu:UInt64,_ r:Int){let n=Int(nu),input=(0..<Int(nu)).map{mix32(UInt32($0))};var h=[UInt32](repeating:0,count:n),t=[Double]();var c:UInt32=0;for _ in 0..<r{let s=now();var sz=0;for x in input{heapPush(&h,&sz,x)};var z:UInt32=0;for i in 0..<n{z ^= heapPop(&h,&sz)&+UInt32(i)};c=z;t.append(now()-s)};let m=median(t);emit("binary_heap",nu,r,m,Double(n*2)/m/1e6,UInt64(c))}
func benchBST(_ nu:UInt64,_ r:Int){let n=Int(nu),input=(0..<Int(nu)).map{mix32(UInt32($0))};var keys=[UInt32](repeating:0,count:n),left=[Int32](repeating:-1,count:n),right=[Int32](repeating:-1,count:n),t=[Double]();var c:UInt32=0;for _ in 0..<r{let s=now();var root:Int32 = -1;for i in 0..<n{let key=input[i];keys[i]=key;left[i] = -1;right[i] = -1;let node=Int32(i);if root<0{root=node;continue};var cur=root;while true{let u=Int(cur);if key<keys[u]{if left[u]<0{left[u]=node;break};cur=left[u]}else{if right[u]<0{right[u]=node;break};cur=right[u]}}};var h:UInt32=0;var i=0;while i<n{let key=input[i];var cur=root;while cur>=0 && keys[Int(cur)] != key{let u=Int(cur);cur=key<keys[u] ? left[u]:right[u]};if cur>=0{h ^= UInt32(cur)+1};i+=3};c=h;t.append(now()-s)};let m=median(t);emit("bst",nu,r,m,Double(n)/m/1e6,UInt64(c))}
func benchTrie(_ nu:UInt64,_ r:Int){let n=Int(nu),passes=32,mx=1+n*8,words=(0..<Int(nu)).map{mix32(UInt32($0))};var ch=[Int32](repeating:-1,count:mx*16),term=[UInt8](repeating:0,count:mx),t=[Double]();var c:UInt32=0;for _ in 0..<r{let s=now();ch=Array(repeating:-1,count:mx*16);term=Array(repeating:0,count:mx);var used=1;for w in words{var node:Int32=0;var sh=28;while sh>=0{let cc=Int((w>>UInt32(sh))&15),idx=Int(node)*16+cc;if ch[idx]<0{ch[idx]=Int32(used);used+=1};node=ch[idx];sh-=4};term[Int(node)]=1};var h=UInt32(used);for p in 0..<passes{var i=0;while i<n{let w=words[i];var node:Int32=0,sh=28;while sh>=0 && node>=0{node=ch[Int(node)*16+Int((w>>UInt32(sh))&15)];sh-=4};if node>=0 && term[Int(node)] != 0{h ^= UInt32(node)+1+UInt32(p)};i+=2}};c=h;t.append(now()-s)};let m=median(t);emit("trie",nu*UInt64(passes),r,m,Double(n*passes)/m/1e6,UInt64(c))}
func defSize(_ k:String)->UInt64{switch k{case "integer50":return 200000000;case "json_escape":return 16000000;case "merge_sort","binary_search","union_find","hash_table","binary_heap":return 1000000;case "prefix_sum":return 8000000;case "matrix_mul":return 320;case "bfs":return 200000;case "dijkstra","trie":return 100000;case "mandelbrot":return 1600;case "dynamic_array":return 5000000;case "linked_list":return 4000000;case "queue_ring":return 10000000;case "bst":return 300000;default:return 0}}
let args=CommandLine.arguments,k=args.count>1 ? args[1]:"integer50",n=args.count>2 ? UInt64(args[2])!:defSize(k),r=args.count>3 ? Int(args[3])!:7
switch k{case "integer50":benchInteger(n,r);case "json_escape":benchJSON(n,r);case "merge_sort":benchMerge(n,r);case "binary_search":benchBS(n,r);case "prefix_sum":benchPrefix(n,r);case "matrix_mul":benchMatrix(n,r);case "bfs":benchBFS(n,r);case "dijkstra":benchDij(n,r);case "union_find":benchUF(n,r);case "mandelbrot":benchMandel(n,r);case "dynamic_array":benchArray(n,r);case "linked_list":benchList(n,r);case "queue_ring":benchQueue(n,r);case "hash_table":benchHash(n,r);case "binary_heap":benchHeap(n,r);case "bst":benchBST(n,r);case "trie":benchTrie(n,r);default:exit(64)}
